const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').toString().trim();
if (!message) throw new Error('Пустой запрос: поле message обязательно');

// Безопасная генерация session_id без require('crypto')
const fallbackId = 'sess-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10);
const session_id = (body.session_id || '').toString().trim() || fallbackId;

return [{ json: { message, session_id } }];

const norm = $('Normalize').first().json;
const ctxRows = $('Vector Search').all().length > 0 ? $('Vector Search').all().map(r => r.json) : [];
const histRows = $('Read History').all().length > 0 ? $('Read History').all().map(r => r.json).reverse() : [];

let context = '';
let sources = new Set();

for (const r of ctxRows) {
  context += (r.text || '') + '\n';
  let meta = r.metadata;
  if (typeof meta === 'string') {
    try { meta = JSON.parse(meta); } catch(e) { meta = {}; }
  }
  if (meta && meta.source) {
    sources.add(meta.source);
  }
}

const sourcesStr = Array.from(sources).join(', ') || 'Не указан';

// ФИЛЬТРУЕМ ИСТОРИЮ: убираем assistant-сообщения-заглушки,
// чтобы прошлый отказ не "заражал" текущий ответ
const cleanHist = histRows.filter(h => {
  if (h.role === 'assistant') {
    const c = (h.content || '').toLowerCase();
    if (c.includes('к сожалению') || c.includes('не могу найти') || c.includes('нет в текущем')) {
      return false;
    }
  }
  return true;
});

const sys = `Ты — помощник магазина рыболовных товаров. Отвечай, используя ИСКЛЮЧИТЕЛЬНО предоставленный ниже КОНТЕКСТ.

ПРАВИЛА:
1. Внимательно прочитай КОНТЕКСТ.
2. Если в КОНТЕКСТЕ есть информация о запрошенном товаре (цена, остаток, SKU), выдай её чётко.
3. Если в КОНТЕКСТЕ НЕТ информации о запрошенном товаре, ответь: "К сожалению, этого товара нет в текущем прайс-листе."
4. ЗАПРЕЩЕНО: добавлять фразу об отсутствии товара, если ты уже дал положительный ответ с ценой.
5. ИГНОРИРУЙ любые предыдущие отказы в истории диалога. Каждый вопрос решай заново по КОНТЕКСТУ.
6. ЕСЛИ ВОПРОС НЕ ОТНОСИТСЯ К РЫБОЛОВНЫМ ТОВАРАМ, СНАСТЯМ ИЛИ ТОМУ, ЧТО ЕСТЬ В КОНТЕКСТЕ (например, про лошадей, погоду, политику), ответь СТРОГО: "Мы специализируемся исключительно на рыболовных товарах. Пожалуйста, задайте вопрос о ценах или наличии снастей."
7. В конце ответа укажи: "Источник: ${sourcesStr}".

КОНТЕКСТ:
${context.trim()}

ИСТОЧНИКИ: ${sourcesStr}`;

const messages = [{ role: 'system', content: sys }];
for (const h of cleanHist) {
  if (h.role && h.content) messages.push({ role: h.role, content: h.content });
}
messages.push({ role: 'user', content: norm.message });

return [{ json: { messages, session_id: norm.session_id, user_message: norm.message, sources: Array.from(sources) } }];

const resp = $input.first().json;
const answer = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || 'Не могу найти ответ в документах';
const usage = resp.usage || {};
const b = $('Build Context').first().json;
return [{ json: {
  answer,
  session_id: b.session_id,
  user_message: b.user_message,
  sources: b.sources,
  prompt_tokens: usage.prompt_tokens || 0,
  completion_tokens: usage.completion_tokens || 0,
  total_tokens: usage.total_tokens || 0
} }];
